// Fast update demo for the Waveshare 2.7in e-Paper HAT V1 on a Waveshare
// RP2040-PiZero. A Utah teapot wireframe rotates about three axes. Only the
// pixels that change are driven, so the rest of the screen does not flash.
//
// The wiring is the same as the epd2in7 slideshow example.
//
// Short custom waveforms can cause image retention. Do not leave this demo
// running for a long time.
//
// The teapot mesh is generated by gen_teapot.go from the University of Utah
// Model Repository teapot_bezier data.
//
// Build and flash:
//
//	tinygo flash -target=waveshare-rp2040-pizero ./examples/waveshare-epd/epd2in7-fast
package main

import (
	"image/color"
	"machine"
	"time"

	"tinygo.org/x/drivers"
	"tinygo.org/x/drivers/waveshare-epd/epd2in7"
)

const (
	cleanEvery   = 60 * time.Second
	reportPeriod = 100
)

var black = color.RGBA{0, 0, 0, 255}

func main() {
	time.Sleep(3 * time.Second)

	err := machine.SPI1.Configure(machine.SPIConfig{
		Frequency: 10000000,
		SCK:       machine.GPIO10,
		SDO:       machine.GPIO11,
		SDI:       machine.GPIO12,
		Mode:      0,
	})
	if err != nil {
		println("SPI configure failed:", err.Error())
		return
	}

	display := epd2in7.New(machine.SPI1, machine.GPIO8, machine.GPIO25, machine.GPIO17, machine.GPIO24)
	display.Configure(epd2in7.Config{
		Rotation: drivers.Rotation270,
	})
	fast := epd2in7.NewFast(&display, epd2in7.FastConfig{})

	start := time.Now()
	display.ClearBuffer()
	drawTeapot(&display, 0)
	fast.Clean()

	lastClean := time.Now()
	lastReport := time.Now()
	for scans := 1; ; scans++ {
		display.ClearBuffer()
		drawTeapot(&display, uint64(time.Since(start).Microseconds()))
		fast.Scan()

		if time.Since(lastClean) > cleanEvery {
			fast.Clean()
			lastClean = time.Now()
		}
		if scans%reportPeriod == 0 {
			println("ms per scan:", time.Since(lastReport).Milliseconds()/reportPeriod)
			lastReport = time.Now()
		}
	}
}
